285	     */
286	    public Pet getPet(String name) {
287	        return getPet(name, false);
288	    }
289	
290	    /**
291	     * Return the Pet with the given name, or null if none found for this Owner.
292	     *
293	     * @param name to test
294	     * @return true if pet name is already in use
295	     */
296	    public Pet getPet(String name, boolean ignoreNew) {
297	        name = name.toLowerCase();
298	        for (Pet pet : getPetsInternal()) {
299	            if (!ignoreNew || !pet.isNew()) {
300	                String compName = pet.getName();
301	                compName = compName.toLowerCase();
302	                if (compName.equals(name)) {
303	                    return pet;
304	                }
305	            }
306	        }
307	        return null;
308	    }
