2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * Rejects a create request that is missing or blank in any required owner field, before
13	 * {@link BuildOwner} runs. Binds the body without {@code @Valid} so the missing fields are
14	 * reported as an {@code errors} array (via {@link MissingOwnerFieldsException}) rather than as
15	 * bean-validation schema errors. This is the only step that binds the body; it republishes it
16	 * for {@link BuildOwner} to consume.
17	 *
18	 * <p>The address is normalized in place first (see {@link AddressNormalizer}). An owner may supply its
19	 * address either in structured form ({@code addressLine1} with an optional {@code addressLine2}) or via
20	 * the flat {@code address} field (backward-compatible); the structured fields are preferred when present,
21	 * falling back to the flat address. The required-field check then rejects an owner that supplies neither.
22	 * The flat {@code address} is republished as the normalized composed value — the normalized
23	 * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended when
24	 * {@code addressLine2} is present — so the stored/returned value and every later address read see it.
25	 */
26	public class ValidateOwnerRequiredFields {
27	
28	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
29	            throws MissingOwnerFieldsException {
30	        String line1 = AddressNormalizer.normalize(request.getAddressLine1());
31	        String line2 = AddressNormalizer.normalize(request.getAddressLine2());
32	        String flat = AddressNormalizer.normalize(request.getAddress());
